kpis('buildKpis',[['Tools analysed',fmt(entries.length),'Customer / unspecified records'],['Use-case categories',fmt(cats.length),'Rule-based classification'],['Leading use case',counts[0]?.name||'None',counts[0]?fmt(counts[0].n)+' tools':'No tools'],['Unclassified',fmt(entries.filter(x=>x.category==='Other / not identifiable').length),'Descriptions insufficient']]);
