 el('auditKpis').innerHTML=[['Reported days',ds.length+' / '+allDates.length,'Within selected calendar coverage'],['Missing daily reports',missing.length,'Not equivalent to 0 usage'],['Reported zero-activity days',zero.length,'Confirmed reports, no token/image/web usage']].map(([l,v,t])=>`<div class="audit-stat"><small>${escapeHTML(l)}</small><strong>${escapeHTML(v)}</strong><small>${escapeHTML(t)}</small></div>`).join('');
 el('auditCoverage').innerHTML=`<div class="audit-note ${missing.length?'audit-alert':'audit-ok'}"><strong>${escapeHTML(org.name)}</strong><p>${ds.length} reported records across ${allDates.length} eligible calendar days. ${missing.length} absent report(s) and ${zero.length} explicitly reported zero-activity day(s).</p>${month==='all'||month==='2026-05'||month==='2026-11'?'<p>May and November are partial calendar months. Never treat them as full-month totals without adjustment.</p>':''}</div>`;
 el('auditMissing').innerHTML=`<h3 style="font-size:13px;margin:13px 0 8px">Missing dates</h3><p class="ex-muted">${missing.length?escapeHTML(missing.slice(0,24).join(' · '))+(missing.length>24?' · … ('+missing.length+' total)':''):'None in the selected period'}</p><h3 style="font-size:13px;margin:16px 0 8px">Explicit zero-activity dates</h3><p class="ex-muted">${zero.length?escapeHTML(zero.map(r=>r.date).join(' · ')):'None in the selected period'}</p>`;
 const sum=(r,k)=>r.reduce((n,x)=>n+Number(x[k]||0),0);
 const insights=[];
 const top=[...ds].sort((a,b)=>Number(b.totalCostUsd)-Number(a.totalCostUsd))[0];
 if(top&&Number(top.totalCostUsd)>0){const n=money(top.totalCostUsd),part=[['AI tokens',Number(top.tokenCostUsd)],['Images',Number(top.imageCostUsd)],['Web search',Number(top.webSearchCostUsd)]].sort((a,b)=>b[1]-a[1])[0];insights.push(['Highest reported usage-cost day',`${top.date} had ${n} in recorded usage costs. Largest recorded component: ${part[0]} (${money(part[1])}).`,'Review that day’s activity in Spending; this observation alone does not establish its cause.']);}
 if(ds.length&&sum(ds,'imagesGenerated')>0)insights.push(['Image-generation activity',`${sum(ds,'imagesGenerated')} images generated in the selected period; recorded image cost ${money(sum(ds,'imageCostUsd'))}.`,'Inspect the image workload and check whether budget or training adjustments are needed.']);
 if(ds.length&&sum(ds,'webSearchRequests')>0)insights.push(['Web-search activity',`${sum(ds,'webSearchRequests')} external web searches; recorded search cost ${money(sum(ds,'webSearchCostUsd'))}.`,'Review external-search demand separately from internal knowledge-base searches.']);
 if(missing.length)insights.push(['Reporting gap',`${missing.length} calendar date(s) have no report in this selection.`,'Investigate data coverage before interpreting utilization declines or comparing costs.']);
 const k=data.kondash,custom=Object.keys(k).filter(type=>Array.isArray(k[type])&&type!=='chats'&&type!=='groups'&&type!=='plugins'&&type!=='memories').flatMap(type=>k[type].filter(x=>x.organizationId===id&&x.origin==='createdByOrganization'));
 if(!custom.length)insights.push(['No customer-created tools in sample',`The KON Dash example records show no tools marked createdByOrganization for this customer.`,'Consider onboarding or a guided starting workflow. Examples are not reconciled with measured usage.']);
